      expect(err).toBeInstanceOf(AgentrackError);
      const e = err as AgentrackError;
      expect(e.result).toBe("ISSUE_MISSING");
    }
  });
});

describe("Edge Cases — Large Number of Events", () => {
  let testDir: string;
  let tracker: Tracker;

  beforeEach(() => {
    testDir = join(
      tmpdir(),
      `agentrack-edge-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    );
    tracker = new Tracker(testDir);
  });

  afterEach(() => {
    rmSync(testDir, { recursive: true, force: true });
  });

  test("100+ update events — view() returns correct computed state", async () => {
    await tracker.init();
