43	    function setAuthMode(mode: "open" | "read-only" | "strict", defaultUser = "anonymous") {
44	      const configPath = join(testDir, ".agentrack", "config.json");
45	      writeFileSync(configPath, JSON.stringify({ auth: { mode, defaultUser } }));
46	    }
47	
